    size_t n = 0;
    const char *p;

    if (trace_fd < 0)
        return;

    for (p = "GETRANDOM req="; *p; p++)
        line[n++] = *p;
    n += fmt_u64(line + n, (unsigned long long)req);
    for (p = " base="; *p; p++)
        line[n++] = *p;
    n += fmt_u64(line + n, base);
    for (p = " ret="; *p; p++)
        line[n++] = *p;
