54	/// The byte the randtrap shim hands to the guest at global draw index `i`
55	/// (see pattern_byte() in randtrap.c).
56	fn pattern_byte(i: usize) -> u8 {
57	    (0x80 + (i % 64)) as u8
58	}
59	
60	/// The first `n` bytes the shim would deliver.
61	fn pattern(n: usize) -> Vec<u8> {
62	    (0..n).map(pattern_byte).collect()
63	}
