73	impl Tmp {
74	    fn new(label: &str) -> Tmp {
75	        static SEQ: AtomicU64 = AtomicU64::new(0);
76	        let path = std::env::temp_dir().join(format!(
77	            "wrapfile-keygen-random-tests-{}-{}-{}",
78	            std::process::id(),
79	            label,
