173	#[derive(Debug)]
174	struct GrEvent {
175	    req: usize,
176	    base: usize, // global draw index of the first byte this call hands out
177	    ret: i64,    // negative: the call failed with the injected errno
178	}
179	
180	impl GrEvent {
181	    fn failed(&self) -> bool {
182	        self.ret < 0
183	    }
184	
185	    fn delivered(&self) -> usize {
186	        if self.ret > 0 { self.ret as usize } else { 0 }
187	    }
188	
189	    /// The pattern bytes this call handed to the guest.
190	    fn bytes(&self) -> Vec<u8> {
191	        (self.base..self.base + self.delivered())
192	            .map(pattern_byte)
193	            .collect()
194	    }
195	}
196	
197	/// The GETRANDOM lines of the trace, in call order.
198	fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
199	    let text = fs::read_to_string(trace).unwrap();
200	    text.lines()
201	        .filter_map(|line| {
202	            let mut parts = line.split_whitespace();
203	            if parts.next() != Some("GETRANDOM") {
204	                return None;
205	            }
206	            let mut req = None;
207	            let mut base = None;
208	            let mut ret = None;
209	            for kv in parts {
210	                let (k, v) = kv.split_once('=')?;
211	                match k {
212	                    "req" => req = v.parse().ok(),
213	                    "base" => base = v.parse().ok(),
214	                    "ret" => ret = v.parse().ok(),
215	                    _ => {}
216	                }
217	            }
218	            Some(GrEvent { req: req?, base: base?, ret: ret? })
219	        })
220	        .collect()
