223	/// The events that make up keygen's own draw of the 32 key bytes. The
224	/// process runtime may draw randomness of its own before main() (and the
225	/// getrandom crate probes the syscall once with a zero-length request), so
226	/// the key fill is identified as the final run of calls starting with a
227	/// full-length (32-byte) request.
228	fn key_fill_events(events: &[GrEvent]) -> &[GrEvent] {
229	    let start = events
230	        .iter()
231	        .rposition(|e| e.req == KEY_LEN)
232	        .expect("keygen must attempt to draw the 32 key bytes");
233	    &events[start..]
234	}
