    while (n) { long r = syscall(SYS_write, trace_fd, s, n); if (r <= 0) return; s += r; n -= r; }
}
static void ts(const char *s) { if (trace_fd >= 0) tw(s, strlen(s)); }
static void thex(unsigned char b) { char c[2] = { "0123456789abcdef"[b>>4], "0123456789abcdef"[b&15] }; tw(c,2); }
static void tnum(unsigned long long v) { char t[20]; int n=0; do { t[n++]='0'+v%10; v/=10; } while(v); while(n){ char c=t[--n]; tw(&c,1);} }

static void check_wipe_state(void)
{
    /* shadow-compare for wide stores */
    for (int i = 0; i < 32; i++) {
        unsigned char cur = key_addr[i];
        if (cur != key_snapshot[i]) {
            if (cur == 0) zeroed[i] = 1;
            else if (!wipe_confirmed) {
                wipe_violated = 1;
                ts("WIPE violated off="); tnum(i); ts("\n");
            }
            key_snapshot[i] = cur;
        }
    }
    if (pending_off >= 0 && pending_off < 32) {
        if (key_addr[pending_off] == 0) zeroed[pending_off] = 1;
        else if (!wipe_confirmed && !wipe_violated) {
            wipe_violated = 1;
            ts("WIPE violated off="); tnum(pending_off); ts("\n");
        }
    }
    pending_off = -1;
    if (!wipe_confirmed && !wipe_violated) {
        int all = 1;
        for (int i = 0; i < 32; i++) if (!zeroed[i]) all = 0;
        if (all) {
            wipe_confirmed = 1;
            ts("WIPE confirmed zeroed=32\n");
            /* disarm */
            mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
            watch_armed = 0;
        }
    }
    if (wipe_violated && watch_armed) {
        mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
        watch_armed = 0;
    }
}

static void on_segv(int sig, siginfo_t *info, void *uctx)
{
    (void)sig;
    uintptr_t a = (uintptr_t)info->si_addr;
    if (watch_armed && a >= watch_lo && a < watch_lo + watch_len) {
        ucontext_t *uc = (ucontext_t *)uctx;
        pending_off = (a >= (uintptr_t)key_addr && a < (uintptr_t)key_addr + 32)
                          ? (int)(a - (uintptr_t)key_addr) : -1;
        mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
        uc->uc_mcontext.gregs[REG_EFL] |= 0x100; /* TF: single-step */
        stepped = 1;
        return;
    }
    /* not ours: chain to the previously installed handler (Rust's) */
    if (saved_segv.sa_sigaction) {
        saved_segv.sa_sigaction(sig, info, uctx);
        return;
    }
    signal(SIGSEGV, SIG_DFL);
    raise(SIGSEGV);
}

static void on_trap(int sig, siginfo_t *info, void *uctx)
{
    (void)sig; (void)info;
    if (stepped) {
        ucontext_t *uc = (ucontext_t *)uctx;
        stepped = 0;
        uc->uc_mcontext.gregs[REG_EFL] &= ~0x100UL;
        mprotect((void *)watch_lo, watch_len, PROT_READ);
        check_wipe_state();
        return;
    }
    signal(SIGTRAP, SIG_DFL);
    raise(SIGTRAP);
}

static void arm_watch(void)
{
    struct sigaction sa;
    stack_t ss;

    watch_lo = (uintptr_t)key_addr & ~(PAGE - 1);
    uintptr_t end = ((uintptr_t)key_addr + 32 + PAGE - 1) & ~(PAGE - 1);
    watch_len = end - watch_lo;

    ss.ss_sp = altstack_base;
    ss.ss_flags = 0;
    ss.ss_size = ALTSTACK_SIZE;
    sigaltstack(&ss, NULL);

    memset(&sa, 0, sizeof sa);
    sa.sa_sigaction = on_segv;
    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGSEGV, &sa, &saved_segv);

    memset(&sa, 0, sizeof sa);
    sa.sa_sigaction = on_trap;
    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTRAP, &sa, NULL);

    if (mprotect((void *)watch_lo, watch_len, PROT_READ) != 0) {
        ts("WATCH unavailable errno=mprotect\n");
        return;
    }
    watch_armed = 1;
    ts("WATCH armed pages="); tnum(watch_len / PAGE); ts("\n");
}

static void on_sigsys(int sig, siginfo_t *info, void *uctx)
{
    (void)sig;
    if (info->si_code != SYS_SECCOMP || info->si_syscall != SYS_getrandom) {
        signal(SIGSYS, SIG_DFL); raise(SIGSYS); return;
    }
    ucontext_t *uc = (ucontext_t *)uctx;
    unsigned char *buf = (unsigned char *)(uintptr_t)uc->uc_mcontext.gregs[REG_RDI];
    size_t len = (size_t)uc->uc_mcontext.gregs[REG_RSI];
    long ret = 0;
    size_t done = 0;
    while (done < len) {
        ssize_t r = read(urandom_fd, buf + done, len - done);
        if (r <= 0) { ret = -EIO; break; }
        done += (size_t)r;
    }
    if (ret == 0) ret = (long)done;
    if (len == 32 && ret == 32 && !have_key) {
        key_addr = buf;
        memcpy(key_snapshot, buf, 32);
        have_key = 1;
        ts("KEYFILL addr=0x");
        unsigned long long a = (unsigned long long)(uintptr_t)buf;
        for (int i = 15; i >= 0; i--) thex((unsigned char)(a >> (i*4)) & 0xf);
        ts(" n=32 hex=");
        for (int i = 0; i < 32; i++) thex(buf[i]);
        ts("\n");
        arm_watch();
    }
    uc->uc_mcontext.gregs[REG_RAX] = ret;
}

__attribute__((destructor))
static void proto_fini(void)
{
    if (!have_key) return;
    if (wipe_confirmed) { ts("WIPE final confirmed\n"); return; }
    if (wipe_violated) { ts("WIPE final violated\n"); return; }
    int nz = 0;
    for (int i = 0; i < 32; i++) if (key_addr[i] != 0) nz++;
    ts("WIPE missing nonzero="); tnum(nz); ts("\n");
}

__attribute__((constructor))
static void proto_init(void)
{
    char pb[512];
    ssize_t n = readlink("/proc/self/exe", pb, sizeof(pb) - 1);
    if (n <= 0) return;
    pb[n] = '\0';
    const char *base = strrchr(pb, '/');
    base = base ? base + 1 : pb;
    if (strncmp(base, "wrapfile", 8) != 0) return;
    if (!getenv("WRAPFILE_PROTO")) return;

    const char *tf = getenv("WRAPFILE_PROTO_TRACE");
    if (tf) trace_fd = open(tf, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
    urandom_fd = open("/dev/urandom", O_RDONLY | O_CLOEXEC);
    altstack_base = mmap(NULL, ALTSTACK_SIZE, PROT_READ | PROT_WRITE,
                         MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_sigaction = on_sigsys;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGSYS, &sa, NULL);

    struct sock_filter filter[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, (unsigned)offsetof(struct seccomp_data, arch)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, TRAP_AUDIT_ARCH, 1, 0),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, (unsigned)offsetof(struct seccomp_data, nr)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_getrandom, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_TRAP),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
    };
    struct sock_fprog prog = { .len = (unsigned short)(sizeof(filter)/sizeof(filter[0])), .filter = filter };
    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0 ||
        prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog) != 0) {
        ts("TRAP unavailable\n");
        return;
    }
    ts("TRAP armed\n");
}
EOF
