265	/* The byte handed out at global draw index `index` in the pattern modes.
266	 * Never a zero byte, so the tests can prove the run handled non-zero
267	 * secret material. */
268	static unsigned char pattern_byte(unsigned long long index)
269	{
270	    return (unsigned char)(0x80 + (index % 64));
271	}
