273	/* ----- the wipe watch ----- */
274	
275	static void disarm_watch(void)
276	{
277	    if (!watch_armed)
278	        return;
279	    mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
280	    watch_armed = 0;
281	}
282	
283	/* Called after every stepped store, with the pages already read-only
284	 * again: fold the store's effect into the zeroed map. */
285	static void check_wipe_state(void)
286	{
287	    int i, all;
288	
289	    /* A wide store may have covered buffer bytes beyond si_addr; any
290	     * change since the snapshot is attributed by its new value. */
291	    for (i = 0; i < KEY_LEN; i++) {
292	        unsigned char cur = key_addr[i];
293	        if (cur == shadow[i])
294	            continue;
295	        if (cur == 0) {
296	            zeroed[i] = 1;
297	        } else if (!wipe_confirmed && !wipe_violated) {
298	            wipe_violated = 1;
299	            trace_str("WIPE violated off=");
300	            trace_u64((unsigned long long)i);
301	            trace_str("\n");
302	        }
303	        shadow[i] = cur;
304	    }
305	
306	    /* The faulting store itself targeted this byte. */
307	    if (pending_off >= 0 && pending_off < KEY_LEN) {
308	        if (key_addr[pending_off] == 0) {
309	            zeroed[pending_off] = 1;
310	        } else if (!wipe_confirmed && !wipe_violated) {
311	            wipe_violated = 1;
312	            trace_str("WIPE violated off=");
313	            trace_u64((unsigned long long)pending_off);
314	            trace_str("\n");
315	        }
316	    }
317	    pending_off = -1;
318	
319	    if (wipe_violated) {
320	        /* The buffer slot was reused before the wipe covered it; there
321	         * is nothing more to watch. */
322	        disarm_watch();
323	        return;
324	    }
325	
326	    if (!wipe_confirmed) {
327	        all = 1;
328	        for (i = 0; i < KEY_LEN; i++)
329	            if (!zeroed[i])
330	                all = 0;
331	        if (all) {
332	            wipe_confirmed = 1;
333	            trace_str("WIPE confirmed zeroed=32\n");
334	            /* The wipe ran; the buffer's lifetime is over, so later
335	             * frame-reuse stores into the slot no longer matter. */
336	            disarm_watch();
337	        }
338	    }
339	}
340	
341	static void on_segv(int sig, siginfo_t *info, void *uctx)
342	{
343	    uintptr_t a = (uintptr_t)info->si_addr;
344	
345	    if (watch_armed && a >= watch_lo && a < watch_lo + watch_len) {
346	        ucontext_t *uc = (ucontext_t *)uctx;
347	        pending_off = (a >= (uintptr_t)key_addr &&
348	                       a < (uintptr_t)key_addr + KEY_LEN)
349	                          ? (int)(a - (uintptr_t)key_addr)
350	                          : -1;
351	#if defined(__x86_64__)
352	        /* Trap flag: the faulting store re-runs, then SIGTRAP fires. */
353	        uc->uc_mcontext.gregs[REG_EFL] |= 0x100UL;
354	#else
355	        /* No user-settable single-step flag on aarch64: plant a BRK right
356	         * after the faulting instruction. Only stores fault on a
357	         * read-only page, and a store never branches, so execution
358	         * always continues at pc+4. */
359	        uint64_t pc = uc->uc_mcontext.pc;
360	        patch_site = (void *)(pc + 4);
361	        patch_page = (uintptr_t)patch_site & ~(uintptr_t)(page_size - 1);
362	        saved_insn = *(uint32_t *)patch_site;
363	        mprotect((void *)patch_page, page_size,
364	                 PROT_READ | PROT_WRITE | PROT_EXEC);
365	        *(uint32_t *)patch_site = 0xD4200000u; /* BRK #0 */
366	        __builtin___clear_cache((char *)patch_site, (char *)patch_site + 4);
367	        mprotect((void *)patch_page, page_size, PROT_READ | PROT_EXEC);
368	#endif
369	        mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
370	        stepped = 1;
371	        return;
372	    }
373	
374	    /* Not one of our watch faults: chain to the handler that was
375	     * installed before us (the Rust runtime's stack-overflow guard). */
376	    if ((saved_segv.sa_flags & SA_SIGINFO) && saved_segv.sa_sigaction) {
377	        saved_segv.sa_sigaction(sig, info, uctx);
378	        return;
379	    }
380	    if (!(saved_segv.sa_flags & SA_SIGINFO) && saved_segv.sa_handler > SIG_IGN) {
381	        saved_segv.sa_handler(sig);
382	        return;
383	    }
384	    signal(SIGSEGV, SIG_DFL);
385	    raise(SIGSEGV);
386	}
387	
388	static void on_trap(int sig, siginfo_t *info, void *uctx)
389	{
390	    ucontext_t *uc = (ucontext_t *)uctx;
391	    (void)sig;
392	    (void)info;
393	
394	    if (stepped) {
395	        stepped = 0;
396	#if defined(__x86_64__)
397	        uc->uc_mcontext.gregs[REG_EFL] &= ~0x100UL;
398	#else
399	        /* Restore the instruction the BRK replaced. The kernel reports
400	         * the BRK's own address as the faulting pc, so returning with pc
401	         * unchanged re-executes the restored instruction. */
402	        mprotect((void *)patch_page, page_size,
403	                 PROT_READ | PROT_WRITE | PROT_EXEC);
404	        *(uint32_t *)patch_site = saved_insn;
405	        __builtin___clear_cache((char *)patch_site, (char *)patch_site + 4);
406	        mprotect((void *)patch_page, page_size, PROT_READ | PROT_EXEC);
407	        if ((void *)uc->uc_mcontext.pc != patch_site)
408	            uc->uc_mcontext.pc = (uint64_t)(uintptr_t)patch_site;
409	#endif
410	        mprotect((void *)watch_lo, watch_len, PROT_READ);
411	        check_wipe_state();
412	        return;
413	    }
414	
415	    /* Not our step: die the way an unhandled SIGTRAP would. */
416	    signal(SIGTRAP, SIG_DFL);
417	    raise(SIGTRAP);
418	}
419	
420	static void arm_watch(void)
421	{
422	    struct sigaction sa;
423	    stack_t ss;
424	    uintptr_t end;
425	
426	    if (watch_armed)
427	        return;
428	
429	    /* The buffer has not been stored to since the fill (the save only
430	     * reads it), so this snapshot is exactly what the source delivered. */
431	    memcpy(shadow, key_addr, KEY_LEN);
432	
433	    watch_lo = (uintptr_t)key_addr & ~(uintptr_t)(page_size - 1);
434	    end = ((uintptr_t)key_addr + KEY_LEN + page_size - 1) &
435	          ~(uintptr_t)(page_size - 1);
436	    watch_len = end - watch_lo;
437	
438	    /* Signal frames must never land on the watched pages: a fault taken
439	     * while the stack pointer sits inside them could not be delivered
440	     * otherwise. */
441	    ss.ss_sp = altstack_base;
442	    ss.ss_flags = 0;
443	    ss.ss_size = ALTSTACK_SIZE;
444	    if (altstack_base)
445	        sigaltstack(&ss, NULL);
446	
447	    memset(&sa, 0, sizeof(sa));
448	    sa.sa_sigaction = on_segv;
449	    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
450	    sigemptyset(&sa.sa_mask);
451	    sigaction(SIGSEGV, &sa, &saved_segv);
452	
453	    memset(&sa, 0, sizeof(sa));
454	    sa.sa_sigaction = on_trap;
455	    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
456	    sigemptyset(&sa.sa_mask);
457	    sigaction(SIGTRAP, &sa, NULL);
458	
459	    if (mprotect((void *)watch_lo, watch_len, PROT_READ) != 0) {
460	        trace_str("WATCH unavailable errno=mprotect\n");
461	        return;
462	    }
463	    watch_armed = 1;
464	    trace_str("WATCH armed pages=");
465	    trace_u64(watch_len / page_size);
466	    trace_str("\n");
467	}
468	
469	/* The key fill is done (32 bytes delivered) or has failed mid-way: record
470	 * what the buffer received. When the fill failed no file is ever created,
471	 * so the wipe follows at once and the watch arms immediately; otherwise
472	 * arming waits for the end of the save (see note_key_open / interposed
473	 * close). Runs inside the SIGSYS handler, before the guest sees the last
474	 * getrandom result. */
475	static void finish_key_fill(int failed)
476	{
477	    int i;
478	
479	    trace_str("KEYFILL n=");
480	    trace_u64((unsigned long long)key_delivered);
481	    trace_str(" hex=");
482	    for (i = 0; i < key_delivered; i++)
483	        trace_hex8(key_addr[i]);
484	    trace_str("\n");
485	
486	    fill_done = 1;
487	    if (failed)
488	        arm_watch();
489	}
490	
491	/* ----- the emulated getrandom ----- */
492	
493	static void trace_getrandom(size_t req, long ret)
494	{
495	    char line[64];
496	    size_t n = 0;
497	    const char *p;
498	
499	    if (trace_fd < 0)
500	        return;
501	    for (p = "GETRANDOM req="; *p; p++)
502	        line[n++] = *p;
503	    n += fmt_u64(line + n, (unsigned long long)req);
504	    for (p = " ret="; *p; p++)
505	        line[n++] = *p;
506	    if (ret < 0) {
507	        for (p = "-1 errno=EIO"; *p; p++)
508	            line[n++] = *p;
509	    } else {
510	        n += fmt_u64(line + n, (unsigned long long)ret);
511	    }
512	    line[n++] = '\n';
513	    trace_write(line, n);
514	}
515	
516	static void on_sigsys(int sig, siginfo_t *info, void *uctx)
517	{
518	    ucontext_t *uc;
519	    unsigned char *buf;
520	    size_t len, allow, i;
521	    long ret;
522	    int is_key_call;
523	
524	    (void)sig;
525	    if (info->si_code != SYS_SECCOMP || info->si_syscall != SYS_getrandom) {
526	        /* Not our trap: die the way an unhandled SIGSYS would. */
527	        signal(SIGSYS, SIG_DFL);
528	        raise(SIGSYS);
529	        return;
530	    }
531	
532	    uc = (ucontext_t *)uctx;
533	#if defined(__x86_64__)
534	    buf = (unsigned char *)(uintptr_t)uc->uc_mcontext.gregs[REG_RDI];
535	    len = (size_t)uc->uc_mcontext.gregs[REG_RSI];
536	#else
537	    buf = (unsigned char *)(uintptr_t)uc->uc_mcontext.regs[0];
538	    len = (size_t)uc->uc_mcontext.regs[1];
539	#endif
540	
541	    /* keygen draws the whole key with one full-length (32-byte) request;
542	     * the first such request identifies the key buffer. Later calls into
543	     * the same 32-byte region are the rest of the same fill (short reads
544	     * or a source that dries up mid-key). */
545	    if (!have_key_addr && len == KEY_LEN) {
546	        key_addr = buf;
547	        have_key_addr = 1;
548	        key_delivered = 0;
549	    }
550	    is_key_call = have_key_addr && buf >= key_addr && buf < key_addr + KEY_LEN;
551	
552	    allow = len;
553	    if (cfg_mode == MODE_FAIL_AFTER && is_key_call) {
554	        long remaining = cfg_arg - key_delivered;
555	        if (remaining <= 0) {
556	            /* The source dried up mid-key: fail without delivering. */
557	            trace_getrandom(len, -1);
558	            ret = -EIO;
559	            goto done;
560	        }
561	        if (allow > (size_t)remaining)
562	            allow = (size_t)remaining;
563	    }
564	
565	    ret = 0;
566	    if (cfg_mode == MODE_REAL) {
567	        size_t done = 0;
568	        while (done < allow) {
569	            ssize_t r = read(urandom_fd, buf + done, allow - done);
570	            if (r <= 0) {
571	                ret = -EIO;
572	                break;
573	            }
574	            done += (size_t)r;
575	        }
576	        if (ret == 0)
577	            ret = (long)done;
578	    } else {
579	        for (i = 0; i < allow; i++)
580	            buf[i] = pattern_byte(draw_index + i);
581	        draw_index += allow;
582	        ret = (long)allow;
583	    }
584	
585	    if (is_key_call && ret > 0)
586	        key_delivered += (int)ret;
587	
588	    trace_getrandom(len, ret);
589	
590	done:
591	    if (is_key_call && (key_delivered == KEY_LEN || ret < 0))
592	        finish_key_fill(ret < 0);
593	    /* The syscall was never executed; the value left in the return
594	     * register of the signal frame is what the guest sees. */
595	#if defined(__x86_64__)
596	    uc->uc_mcontext.gregs[REG_RAX] = ret;
597	#else
598	    uc->uc_mcontext.regs[0] = (unsigned long long)(long long)ret;
599	#endif
600	}
601	
602	/* ----- tracking the key file's descriptor to time the watch ----- */
603	
604	/* The first O_CREAT open after the key fill is the key file. Its close
605	 * ends the save on every path that creates the file (success, and the
606	 * abort-save cleanup after a permission/write/sync/close-stage failure),
607	 * and the wipe runs right after -- so the watch arms at the close. If
608	 * the create itself fails, the wipe follows on the error path and the
609	 * watch arms immediately. */
610	
611	typedef int (*open_fn)(const char *, int, ...);
612	static open_fn real_open = 0;
613	static open_fn real_open64 = 0;
614	
615	static void note_key_open(int fd, int flags)
616	{
617	    if (!active || !fill_done || key_fd != -2 || !(flags & O_CREAT))
618	        return;
619	    if (fd >= 0) {
620	        key_fd = fd;
621	    } else {
622	        key_fd = -1;
623	        arm_watch();
624	    }
625	}
626	
627	int open(const char *path, int flags, ...)
628	{
629	    mode_t mode = 0;
630	    va_list ap;
631	    int fd;
632	    if (!real_open)
633	        real_open = (open_fn)dlsym(RTLD_NEXT, "open");
634	    if (flags & O_CREAT) {
635	        va_start(ap, flags);
636	        mode = va_arg(ap, mode_t);
637	        va_end(ap);
638	    }
639	    fd = real_open(path, flags, mode);
640	    note_key_open(fd, flags);
641	    return fd;
642	}
643	
644	int open64(const char *path, int flags, ...)
645	{
646	    mode_t mode = 0;
647	    va_list ap;
648	    int fd;
649	    if (!real_open64)
650	        real_open64 = (open_fn)dlsym(RTLD_NEXT, "open64");
651	    if (flags & O_CREAT) {
652	        va_start(ap, flags);
653	        mode = va_arg(ap, mode_t);
654	        va_end(ap);
655	    }
656	    fd = real_open64(path, flags, mode);
657	    note_key_open(fd, flags);
658	    return fd;
659	}
660	
661	typedef int (*close_fn)(int);
662	static close_fn real_close = 0;
663	
664	int close(int fd)
665	{
666	    if (active && fill_done && key_fd >= 0 && fd == key_fd) {
667	        key_fd = -1; /* once: the descriptor number may be reused */
668	        arm_watch();
669	    }
670	    if (!real_close)
671	        real_close = (close_fn)dlsym(RTLD_NEXT, "close");
672	    return real_close(fd);
673	}
674	
675	/* ----- syscalls that write results into the watched stack pages ----- */
676	
677	/* The kernel returns EFAULT instead of signalling when a syscall's output
678	 * buffer sits in a read-only page, and keygen fstats the key file with the
679	 * stat struct on the stack. Lift the watch protection just for the real
680	 * call; no guest instruction runs meanwhile, so the key buffer cannot be
681	 * stored to unobserved through this window. */
682	
683	static int overlaps_watch(const void *p, size_t n)
684	{
685	    uintptr_t a = (uintptr_t)p;
686	    uintptr_t b = a + n;
687	    return watch_armed && a < watch_lo + watch_len && b > watch_lo;
688	}
689	
690	typedef int (*fstat_fn)(int, struct stat *);
691	static fstat_fn real_fstat = 0;
692	
693	int fstat(int fd, struct stat *st)
694	{
695	    int r;
696	    if (!real_fstat)
697	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
698	    if (!overlaps_watch(st, sizeof(*st)))
699	        return real_fstat(fd, st);
700	    mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
701	    r = real_fstat(fd, st);
702	    mprotect((void *)watch_lo, watch_len, PROT_READ);
703	    return r;
704	}
705	
706	#ifdef __USE_LARGEFILE64
707	typedef int (*fstat64_fn)(int, struct stat64 *);
708	static fstat64_fn real_fstat64 = 0;
709	
710	int fstat64(int fd, struct stat64 *st)
711	{
712	    int r;
713	    if (!real_fstat64)
714	        real_fstat64 = (fstat64_fn)dlsym(RTLD_NEXT, "fstat64");
715	    if (!overlaps_watch(st, sizeof(*st)))
716	        return real_fstat64(fd, st);
717	    mprotect((void *)watch_lo, watch_len, PROT_READ | PROT_WRITE);
718	    r = real_fstat64(fd, st);
719	    mprotect((void *)watch_lo, watch_len, PROT_READ);
720	    return r;
721	}
722	#endif
723	
724	/* ----- first output after the key fill (ordering evidence) ----- */
725	
726	typedef ssize_t (*write_fn)(int, const void *, size_t);
727	static write_fn real_write = 0;
728	
729	ssize_t write(int fd, const void *buf, size_t count)
730	{
731	    if (!real_write)
732	        real_write = (write_fn)dlsym(RTLD_NEXT, "write");
733	    if (active && have_key_addr && !output_seen && (fd == 1 || fd == 2)) {
734	        output_seen = 1;
735	        trace_str("OUTPUT fd=");
736	        trace_u64((unsigned long long)fd);
737	        trace_str("\n");
738	    }
739	    return real_write(fd, buf, count);
740	}
741	
742	/* ----- final verdict ----- */
743	
744	__attribute__((destructor))
745	static void keywipe_fini(void)
746	{
747	    int i, nonzero;
748	
749	    if (!active || !have_key_addr)
750	        return;
751	    if (wipe_confirmed) {
752	        trace_str("WIPE final confirmed\n");
753	        return;
754	    }
755	    if (wipe_violated) {
756	        trace_str("WIPE final violated\n");
757	        return;
758	    }
759	    /* The watch was still armed at exit: the buffer was never fully
760	     * zeroed. Whatever it still holds (the key itself, or frame-reuse
761	     * residue where the key used to be), the wipe never ran to
762	     * completion before the operation returned. */
763	    nonzero = 0;
764	    for (i = 0; i < KEY_LEN; i++)
765	        if (key_addr[i] != 0)
766	            nonzero++;
767	    trace_str("WIPE missing nonzero=");
768	    trace_u64((unsigned long long)nonzero);
769	    trace_str("\n");
770	}
771	
772	/* ----- constructor: arm the getrandom trap when a mode is configured ----- */
773	
774	__attribute__((constructor))
775	static void keywipe_init(void)
776	{
777	    const char *v;
778	    struct sigaction sa;
779	    struct sock_filter filter[] = {
780	        BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
781	                 (unsigned)offsetof(struct seccomp_data, arch)),
782	        /* Arch match: fall through to the syscall-number check. Anything
783	         * else (a compat/foreign-ABI syscall) is simply never trapped. */
784	        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, TRAP_AUDIT_ARCH, 1, 0),
785	        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
786	        BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
787	                 (unsigned)offsetof(struct seccomp_data, nr)),
788	        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_getrandom, 0, 1),
789	        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_TRAP),
790	        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
791	    };
792	    struct sock_fprog prog = {
793	        .len = (unsigned short)(sizeof(filter) / sizeof(filter[0])),
794	        .filter = filter,
795	    };
796	
797	    if (!process_active())
798	        return;
799	
800	    if (getenv("WRAPFILE_TEST_KEYWIPE_PATTERN")) {
801	        cfg_mode = MODE_PATTERN;
802	    } else if ((v = getenv("WRAPFILE_TEST_KEYWIPE_FAIL_AFTER")) && v[0]) {
803	        cfg_mode = MODE_FAIL_AFTER;
804	        cfg_arg = strtol(v, NULL, 10);
805	    } else if (getenv("WRAPFILE_TEST_KEYWIPE")) {
806	        cfg_mode = MODE_REAL;
807	    } else {
808	        return;
809	    }
810	    active = 1;
811	
812	    page_size = (unsigned long)sysconf(_SC_PAGESIZE);
813	    if (page_size == 0)
814	        page_size = 4096;
815	
816	    /*
817	     * Raw openat(AT_FDCWD, ...) rather than open(): when another shim
818	     * (permfail) is preloaded alongside, its open() interposition would
819	     * otherwise track these descriptor opens as guest file creations.
820	     */
821	    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")) && v[0])
822	        trace_fd = (int)syscall(SYS_openat, AT_FDCWD, v,
823	                                O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
824	
825	    urandom_fd = (int)syscall(SYS_openat, AT_FDCWD, "/dev/urandom",
826	                              O_RDONLY | O_CLOEXEC, 0);
827	
828	    altstack_base = mmap(NULL, ALTSTACK_SIZE, PROT_READ | PROT_WRITE,
829	                         MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
830	    if (altstack_base == MAP_FAILED)
831	        altstack_base = 0;
832	
833	    memset(&sa, 0, sizeof(sa));
834	    sa.sa_sigaction = on_sigsys;
835	    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
836	    sigemptyset(&sa.sa_mask);
837	    if (sigaction(SIGSYS, &sa, NULL) != 0) {
838	        trace_str("TRAP unavailable errno=SIGACTION\n");
839	        active = 0;
840	        return;
841	    }
842	
843	    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0 ||
844	        prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog) != 0) {
845	        /* No seccomp on this kernel: leave the real random source alone
846	         * and let the tests skip themselves. */
847	        trace_str("TRAP unavailable errno=SECCOMP\n");
848	        active = 0;
849	        return;
850	    }
851	
852	    trace_str("TRAP armed\n");
853	}
